transforms.code:
# In the session's language: the sentence comes from templates ({count} {units} of {item}...), as a label with numbers in it
# doesn't match a translation term
locale = self.session.props.locale
tr = lambda s: system.util.translate(s, locale)
count = system.kanoa.utilities.formatNumber('#,##0.#', value['outfeedCount'] or 0)
item = value['itemName'] + ' - ' + value['itemDescription'] if value['itemDescription'] else value['itemName']
text = tr('{count} {units} of {item}').replace('{count}', count).replace('{units}', value['outfeedUnits'] or '').replace('{item}', item or '')
#Units made as a co-product of another item, on a family tool, took no time of this item's own (868mu5ca9)
try:
	coProduct = value['coProductCount'] or 0
except:
	coProduct = 0
if coProduct and coProduct >= (value['outfeedCount'] or 0): return tr('{text}, as a co-product').replace('{text}', text)
if coProduct: text = tr('{text} ({count} as a co-product)').replace('{text}', text).replace('{count}', system.kanoa.utilities.formatNumber('#,##0.#', coProduct))
return tr('{text} produced in {time}').replace('{text}', text).replace('{time}', system.kanoa.utilities.secondsToText(value['durationSecs'] or 0, {'showSecs': False, 'roundUp': True}))
